INSERT INTO public.activity_logs (class_id, created_by, title, description, activity_type, created_at)
VALUES
  ('10000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000007', 'ប្រគល់រង្វាន់លើកទឹកចិត្តសិស្សពូកែគណិតវិទ្យា', 'បានផ្តល់រង្វាន់ប៊ិចសៀវភៅដល់សិស្សទទួលបាននិទ្ទេស A ប្រចាំខែ', 'award', NOW() - INTERVAL '2 hour'),
  ('10000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000007', 'បញ្ចូលពិន្ទុប្រចាំខែសីហា រួចរាល់ ១០០%', 'សិស្សទាំង ២៤ នាក់ត្រូវបានបញ្ចូលពិន្ទុ និងចំណាត់ថ្នាក់ត្រឹមត្រូវ', 'report', NOW() - INTERVAL '1 day'),
  ('10000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000007', 'កិច្ចប្រជុំមាតាបិតាសិស្សត្រីមាសទី១', 'បានពិភាក្សាលើវឌ្ឍនភាពសិក្សា និងការចូលរួមរបស់សិស្ស', 'attendance', NOW() - INTERVAL '3 day'),
  ('10000000-0000-0000-0000-000000000012', '00000000-0000-0000-0000-000000000012', 'បំប៉នសិស្សត្រៀមប្រឡងបាក់ឌុប', 'បានរៀបចំថ្នាក់បំប៉នបន្ថែមមុខវិជ្ជាគណិតវិទ្យា និងរូបវិទ្យា', 'award', NOW() - INTERVAL '4 hour');
